export function paintedCardAsset(card:Card,recipe=cardArtRecipe(card)):PaintedAsset{
  const explicit=PAINTED_OVERRIDES[card.id];if(explicit)return explicit;
  const choices=variants[recipe.subject];return choices?choices[recipe.seed%choices.length]:basicAsset(recipe.subject);
}
export function paintedHeroAsset(heroClass:HeroClass):PaintedAsset{return `hero-${heroClass}`;}
export function paintedPowerAsset(heroClass:HeroClass):PaintedAsset{return basicAsset(powerArtRecipe(heroClass).subject);}

